import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    info = {}  # id -> dict(side, price, qty, active)
    seq_counter = 0

    def clean_buy():
        while buy_heap:
            negp, seq, oid = buy_heap[0]
            d = info.get(oid)
            if d is None or not d['active'] or d['qty'] <= 0:
                heapq.heappop(buy_heap)
                continue
            return buy_heap[0]
        return None

    def clean_sell():
        while sell_heap:
            p, seq, oid = sell_heap[0]
            d = info.get(oid)
            if d is None or not d['active'] or d['qty'] <= 0:
                heapq.heappop(sell_heap)
                continue
            return sell_heap[0]
        return None

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            d = info.get(oid)
            if d is not None and d['active'] and d['qty'] > 0:
                d['active'] = False
            continue

        seq_counter += 1
        seq = seq_counter

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            while remaining > 0:
                top = clean_sell()
                if top is None:
                    break
                sp, sseq, sid = top
                if price is not None and sp > price:
                    break
                d = info[sid]
                trade_qty = min(remaining, d['qty'])
                trades.append([oid, sid, sp, trade_qty])
                d['qty'] -= trade_qty
                remaining -= trade_qty
                if d['qty'] <= 0:
                    d['active'] = False
                    heapq.heappop(sell_heap)
        else:  # sell
            while remaining > 0:
                top = clean_buy()
                if top is None:
                    break
                negp, bseq, bid = top
                bp = -negp
                if price is not None and bp < price:
                    break
                d = info[bid]
                trade_qty = min(remaining, d['qty'])
                trades.append([bid, oid, bp, trade_qty])
                d['qty'] -= trade_qty
                remaining -= trade_qty
                if d['qty'] <= 0:
                    d['active'] = False
                    heapq.heappop(buy_heap)

        if typ == 'limit' and remaining > 0:
            info[oid] = {'side': side, 'price': price, 'qty': remaining, 'active': True}
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq, oid))
            else:
                heapq.heappush(sell_heap, (price, seq, oid))
        else:
            # ioc/market remainder discarded, or limit fully filled
            if typ == 'limit':
                info[oid] = {'side': side, 'price': price, 'qty': 0, 'active': False}
            else:
                info[oid] = {'side': side, 'price': price, 'qty': 0, 'active': False}

    return trades

